'use strict';

/**
 * Merge overlapping or touching integer ranges.
 *
 * @param {Array<[number, number]>} ranges - [start, end] pairs with start <= end, in any order.
 * @returns {Array<[number, number]>} New array of non-overlapping ranges sorted ascending by start.
 */
function mergeOverlappingRanges(ranges) {
  const sorted = ranges
    .map(([start, end]) => [start, end])
    .sort((a, b) => a[0] - b[0]);

  const merged = [];
  for (const range of sorted) {
    const last = merged[merged.length - 1];
    if (last && range[0] <= last[1]) {
      last[1] = Math.max(last[1], range[1]);
    } else {
      merged.push(range);
    }
  }
  return merged;
}

module.exports = { mergeOverlappingRanges };

